fn to_uppercase(str1: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(str1.len());
    for &c in str1.iter() {
        if ('a'..='z').contains(&c) {
            // Safe for ASCII lowercase: maps directly to ASCII uppercase.
            let upper = ((c as u8) - b'a' + b'A') as char;
            result.push(upper);
        } else {
            result.push(c);
        }
    }
    result
}